def unique_paths(grid):
 rows = len(grid)
 cols = len(grid[0])

 dp = [[0 for i in range(cols)] for j in range(rows)]

 for i in range(rows):
 for j in range(cols):
 if i == 0 or j == 0:
 dp[i][j] = 1
 else:
 dp[i][j] = dp[i][j-1] + dp[i-1][j]

 return dp[-1][-1]

